                responseStatus, responseBody, commandKey);
    }
}
package com.example.starter.incident;

import java.time.Instant;

/**
 * 命令幂等键实体，对应 command_keys 表。
 * requestHash 为请求规范化参数的摘要；responseBody 为首次成功响应的 JSON，
 * 用于同键同参重放；responseStatus/responseBody 在事务提交前必定写入。
 */
public record CommandKeyRecord(
        long id,
        String commandKey,
        String operation,
        String requestHash,
        Integer responseStatus,
        String responseBody,
        Instant createdAt) {
}
package com.example.starter.incident;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带可区分的 HTTP 状态码与错误码。
 * 400 参数非法，404 资源不存在，409 权限/状态/幂等冲突，422 非法状态流转。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;
    private final transient Object details;

    private ApiException(HttpStatus status, String code, String message, Object details) {
        super(message);
        this.status = status;
        this.code = code;
        this.details = details;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    /** 结构化错误明细（如未完成任务的 groupCode/taskKey、未解除阻塞的事件键列表），无则 null。 */
    public Object details() {
        return details;
    }

    /** 400：请求参数缺失或非法。 */
    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, "BAD_REQUEST", message, null);
    }

    /** 404：事件不存在。 */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message, null);
    }

    /** 409：权限冲突、状态冲突或幂等键冲突。 */
    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, "CONFLICT", message, null);
    }

    /** 409：携带结构化明细的冲突（如解决门禁未完成项、任务未解除阻塞事件列表）。 */
    public static ApiException conflict(String message, Object details) {
        return new ApiException(HttpStatus.CONFLICT, "CONFLICT", message, details);
    }

    /** 422：非法状态流转。 */
    public static ApiException illegalTransition(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "ILLEGAL_TRANSITION", message, null);
    }
}
package com.example.starter.incident;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 统一错误响应：业务异常按 ApiException 携带的状态码返回，
 * 请求体/请求头解析失败归为 400，其余未预期异常归为 500。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * 错误响应体：code 为机器可区分错误码，message 为人读描述；
     * details 为可选结构化明细（如解决门禁未完成项、未解除阻塞的事件键列表），无则 null。
     */
    public record ErrorBody(String code, String message, Object details) {
    }

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(new ErrorBody(ex.code(), ex.getMessage(), ex.details()));
    }

    @ExceptionHandler({HttpMessageNotReadableException.class, MissingRequestHeaderException.class})
    public ResponseEntity<ErrorBody> handleBadRequest(Exception ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody("BAD_REQUEST", "请求格式非法: " + ex.getMessage(), null));
    }
}

