                .andExpect(status().isOk())
                .andExpect(jsonPath("$.taskKey").value(taskKey))
                .andExpect(jsonPath("$.status").value("OPEN"));
    }

    private void changeStatus(String incidentKey, String actor, String target) throws Exception {
